const definitions=[['frequency','How often is the task performed?',['Rarely','Monthly','Weekly','Daily']],['repeatability','How consistent are the steps?',['Different every time','Mostly variable','Mostly repeatable','Clearly repeatable']],['verifiability','How easily can output be checked?',['Very difficult','Needs deep expertise','Reviewable with effort','Quickly checked']],['readiness','How ready is the input data?',['Unavailable','Fragmented','Mostly usable','Structured and reliable']],['sensitive','What data would it use?',['Public or synthetic','Internal non-sensitive','Personal or confidential','Highly sensitive']],['impact','What happens if it is wrong?',['Minor inconvenience','Rework or delay','Financial or customer harm','Rights, safety or employment impact']],['reversal','How reversible are its actions?',['Draft only; no action','Easy to undo','Difficult to undo','Effectively irreversible']],['review','Is qualified human review available?',['No','Not reliably','Yes, before action','Yes, with clear ownership']]];
const $=id=>document.getElementById(id);definitions.forEach(([id,label,options])=>{const l=document.createElement('label');l.htmlFor=id;l.textContent=label;const s=document.createElement('select');s.id=id;options.forEach((text,value)=>s.add(new Option(text,value)));$('fields').append(l,s)});
function assess(v){const score=Math.round((v.frequency+v.repeatability+v.verifiability+v.readiness)/12*100);const reasons=[];let verdict,next;if(v.impact>=2||v.reversal>=2){verdict='Specialist review before automation';next='Map the decision and keep it human-owned. Explore draft-only assistance using synthetic data; involve the relevant domain and governance specialists.';reasons.push('Errors could have significant consequences or actions may be difficult to reverse.')}else if(v.sensitive>=2||v.review<2){verdict='Put safeguards in place first';next='Confirm approved data handling and assign a qualified reviewer before testing any live workflow.';reasons.push('Sensitive inputs or missing reliable human review need attention.')}else if(score>=67){verdict='Consider a limited, supervised pilot';next='Test on 20 representative examples. Compare quality, errors and total time—including review—against the existing process.';}else if(score>=34){verdict='Start with assistive use';next='Use AI for drafts only. Clarify inputs and acceptance criteria, then measure whether checking the output outweighs the time saved.';}else{verdict='Clarify the process first';next='Document the steps and improve input quality before choosing an AI tool.';}if(v.verifiability<=1)reasons.push('Output is hard to verify; design an evaluation method before a pilot.');if(v.readiness<=1)reasons.push('Inputs need preparation; this may reduce the practical value.');if(!reasons.length)reasons.push('Repeatability, usable inputs and human checking make this worth exploring—not a guarantee of value.');return{score,verdict,next,reasons};}
const examples={summaries:[3,3,3,2,1,0,0,3],refunds:[3,3,2,3,2,2,2,3],hiring:[2,1,1,2,3,3,3,2]};const names={summaries:'Draft meeting summaries',refunds:'Approve customer refunds',hiring:'Rank candidates for hiring'};let latest;
function render(){const v=Object.fromEntries(definitions.map(([id])=>[id,Number($(id).value)]));latest={task:$('task').value.trim()||'Untitled task',inputs:v,...assess(v)};$('taskTitle').textContent=latest.task;$('score').textContent=latest.score+' / 100';$('fill').style.width=latest.score+'%';$('verdict').textContent=latest.verdict;$('next').textContent=latest.next;$('reasons').replaceChildren(...latest.reasons.map(t=>{const li=document.createElement('li');li.textContent=t;return li}));}
document.querySelectorAll('[data-example]').forEach(b=>b.onclick=()=>{const k=b.dataset.example;definitions.forEach(([id],i)=>$(id).value=examples[k][i]);$('task').value=names[k];render()});$('form').onsubmit=e=>{e.preventDefault();render()};$('export').onclick=()=>{render();const blob=new Blob([JSON.stringify({...latest,disclaimer:'Illustrative fixed-rule learning prototype, not a validated assessment.'},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='ai-task-assessment.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};definitions.forEach(([id],i)=>$(id).value=examples.summaries[i]);render();
if(typeof module!=='undefined')module.exports={assess};
